3	import { useEffect, useRef, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import Link from "next/link";
6	import { Icon } from "./Icon";
7	import { Panel, StatCard } from "./PageShell";
8	import { NewTicketForm, ReplyForm, TicketStatusButton } from "@/components/customer/TicketForms";
9	import { MessageAttachment } from "@/components/support/MessageAttachment";
10	import { EditableMessageBody } from "@/components/support/EditableMessageBody";
11	import { getTicketThread, getTypingStatus, type TicketThread } from "@/lib/actions-support";
12	import ChatWidget, { type ChatViewer } from "@/components/ChatWidget";
13	
14	type Ticket = {
15	  id: string; subject: string; status: string; priority: string;
16	  updated: string; preview: string; lastFromStaff: boolean;
17	};
18	
19	type CompStatus = "operational" | "degraded" | "down";
20	type HealthComponent = "web" | "db" | "worker" | "proxmox";
21	
22	type StatusData = {
23	  overall: CompStatus;
24	  components: { key: HealthComponent; label: string; status: CompStatus; uptimePct: number | null }[];
25	  incidents: { id: string; title: string; body: string; severity: "degraded" | "down" | "maintenance"; startedAt: string; resolvedAt: string | null }[];
26	};
27	
28	type HelpSectionLite = { name: string; slug: string; emoji: string; blurb: string; count: number };
29	
30	/* The real TicketStatus values, said in the customer's language. CUSTOMER_REPLY
31	   means they have answered and staff have not come back yet — "With support" is
32	   what that means to the person waiting, and it is the honest way round. */
33	/* `.badge`'s own tone variants (app/globals.css) swap the WHOLE gradient
34	   background, not just the text colour — badge-mint/-amber/-rose/-cyan each
35	   carry their own already-contrasting text colour baked in. Layering a bare
36	   `text-*` utility on top of the DEFAULT badge (a fixed blue-violet
37	   gradient) is what produced green/amber/cyan text sitting on a blue pill —
38	   the actual bug being fixed here. `tone: ""` deliberately means "the plain
39	   badge, no variant" for the two neutral/no-action-needed states, matching
40	   BillingView's identical StatusPill convention.
41	   ---
42	   Superseded by the light-not-shape tag study: no pill, no fill, no border —
43	   a small glowing dot with an off-axis bleed (the same directional glow
44	   language the sidebar's active row uses) and plain white text. `tone` here
45	   is one of nx-tag's real hue keys, not a `badge-*` class. `pulse` is set
46	   only on the states where something is actually waiting on an action —
47	   OPEN, ANSWERED and URGENT/HIGH — a breathing glow, not a hard blink,
48	   because several of these can be visible in one table at once. */
49	const STATUS: Record<string, { label: string; tone: string; pulse?: boolean }> = {
50	  OPEN:           { label: "Open",          tone: "amber", pulse: true },
51	  ANSWERED:       { label: "Reply waiting", tone: "cyan",  pulse: true },
52	  CUSTOMER_REPLY: { label: "With support",  tone: "slate" },
53	  CLOSED:         { label: "Closed",        tone: "mint" },
54	};
55	
56	const PRIORITY: Record<string, { label: string; tone: string; pulse?: boolean }> = {
57	  LOW:    { label: "Low",    tone: "slate" },
58	  NORMAL: { label: "Normal", tone: "slate" },
59	  HIGH:   { label: "High",   tone: "amber", pulse: true },
60	  URGENT: { label: "Urgent", tone: "rose",  pulse: true },
61	};
62	
63	/** The tag itself — no pill, no fill, no border. A small glowing dot with an
64	 *  off-axis bleed, plain white text (or dim grey for the neutral "slate"
65	 *  tone, which never glows at all — the absence of light IS the signal that
66	 *  nothing here needs a look). See the "light, not shape" study. */
67	function StatusTag({ label, tone, pulse, className = "" }: {
68	  label: string; tone: string; pulse?: boolean; className?: string;
69	}) {
70	  /* The neutral tone used to render as bare text with no dot at all — the
71	     idea being that an absence of light is itself the signal. In practice it
72	     read as the column being empty/broken rather than "quiet on purpose":
73	     nothing marks where a status is even supposed to be. Every tone now gets
74	     the same dot + label shape; slate's dot just never lights up. Structure
75	     stays constant, only the light changes. */
76	  return (
77	    <span className={"nx-tag nx-tag-" + tone + (pulse ? " nx-tag-pulse" : "") + " " + className}>
78	      <span className="nx-tag-dot" aria-hidden />
79	      {label}
80	    </span>
81	  );
82	}
83	
84	const TICKET_FILTERS: { key: string; label: string; match: (t: Ticket) => boolean }[] = [
85	  { key: "all", label: "All statuses", match: () => true },
86	  { key: "open", label: "Open", match: (t) => t.status !== "CLOSED" },
87	  { key: "waiting", label: "Waiting for you", match: (t) => t.status === "ANSWERED" },
88	  { key: "closed", label: "Closed", match: (t) => t.status === "CLOSED" },
89	];
90	
91	const STATUS_DOT: Record<CompStatus, string> = {
92	  operational: "bg-emerald-400",
93	  degraded: "bg-amber-400",
94	  down: "bg-red-400",
95	};
96	const OVERALL_TITLE: Record<CompStatus, string> = {
97	  operational: "All systems operational",
98	  degraded: "Some systems are degraded",
99	  down: "We're experiencing an outage",
100	};
101	
102	const TABS = [
103	  { key: "tickets", label: "My Tickets", icon: "chatdots" },
104	  { key: "chat", label: "Live Chat", icon: "chatsupport" },
105	  { key: "help", label: "Help Center", icon: "lifebuoy" },
106	  { key: "status", label: "Service Status", icon: "monitor" },
107	] as const;
108	type TabKey = (typeof TABS)[number]["key"];
109	
110	function ago(iso: string): string {
111	  const m = Math.max(1, Math.round((Date.now() - new Date(iso).getTime()) / 60000));
112	  if (m < 60) return `${m}m ago`;
113	  const h = Math.round(m / 60);
114	  if (h < 24) return `${h}h ago`;
115	  return `${Math.round(h / 24)}d ago`;
116	}
117	
118	/** The real cuid, shortened for a scannable reference column — not an
119	 *  invented sequence number, just less of the real id. */
120	function shortRef(id: string): string {
121	  return "#" + id.slice(-6).toUpperCase();
122	}
123	
124	export function SupportView({
125	  viewer, viewerId, tickets, open, waitingOnYou, closedRecently, avgResponseMin, initialTicketId,
126	  help, helpTotal, status,
127	}: {
128	  viewer: ChatViewer;
129	  /** The signed-in customer's own id — needed only so the thread view can
130	   *  tell "my message, still in the 5-minute edit window" apart from a staff
131	   *  reply; everything else here already scopes to this user server-side. */
132	  viewerId: string;
133	  tickets: Ticket[]; open: number; waitingOnYou: number; closedRecently: number;
134	  avgResponseMin: number | null;
135	  initialTicketId: string | null;
136	  help: HelpSectionLite[]; helpTotal: number;
137	  status: StatusData;
138	}) {
139	  const router = useRouter();
140	  const [tab, setTab] = useState<TabKey>("tickets");
141	  const [q, setQ] = useState("");
142	  const [filter, setFilter] = useState("all");
143	  const [newTicketOpen, setNewTicketOpen] = useState(false);
144	
145	  const [openTicket, setOpenTicket] = useState<TicketThread | null>(null);
146	  const [ticketErr, setTicketErr] = useState<string | null>(null);
147	  const [ticketLoading, setTicketLoading] = useState(false);
148	  const [staffTyping, setStaffTyping] = useState(false);
149	  const openedInitial = useRef(false);
150	
151	  async function openTicketById(id: string) {
152	    setTicketErr(null);
153	    setTicketLoading(true);
154	    const res = await getTicketThread(id);
155	    setTicketLoading(false);
156	    if ("error" in res) { setTicketErr("That ticket couldn't be found."); return; }
157	    setOpenTicket(res);
158	    router.replace(`/dashboard/support?ticket=${id}`, { scroll: false });
159	  }
160	
161	  async function refreshOpenTicket(id: string) {
162	    const res = await getTicketThread(id);
163	    if (!("error" in res)) setOpenTicket(res);
164	  }
165	
166	  function backToList() {
167	    setOpenTicket(null);
168	    setTicketErr(null);
169	    router.replace("/dashboard/support", { scroll: false });
170	  }
171	
172	  // A deep link (?ticket=, or the redirect shim at /dashboard/support/[id])
173	  // opens straight into that ticket's thread, once, on first mount.
174	  useEffect(() => {
175	    if (openedInitial.current) return;
176	    openedInitial.current = true;
177	    if (initialTicketId) { setTab("tickets"); void openTicketById(initialTicketId); }
178	    // eslint-disable-next-line react-hooks/exhaustive-deps
179	  }, [initialTicketId]);
180	
181	  // No revalidatePath re-render reaches this client-held thread (it isn't
182	  // server-rendered), so it polls for a staff reply the same way ChatWidget
183	  // polls its own transcript — ReplyForm/TicketStatusButton's onSent/onChanged
184	  // callbacks below cover the customer's OWN actions immediately; this covers
185	  // staff answering while the customer has the thread open. 3s (down from 5s)
186	  // so a staff reply feels like it "just appears" rather than something you
187	  // notice arrived a few seconds late.
188	  useEffect(() => {
189	    if (!openTicket) return;
190	    const id = openTicket.id;
191	    const t = setInterval(() => { void refreshOpenTicket(id); }, 3000);
192	    return () => clearInterval(t);
193	  }, [openTicket?.id]);
194	
195	  // "Staff is typing" — a much faster, much cheaper poll than the thread
196	  // refresh above (getTypingStatus reads an in-memory map, no DB query), so
197	  // it can run quickly enough to feel live without hammering the database.
198	  useEffect(() => {
199	    setStaffTyping(false);
200	    if (!openTicket || openTicket.status === "CLOSED") return;
201	    const id = openTicket.id;
202	    let cancelled = false;
203	    const t = setInterval(async () => {
204	      const res = await getTypingStatus(id);
205	      if (!cancelled) setStaffTyping(res.typing);
206	    }, 1200);
207	    return () => { cancelled = true; clearInterval(t); };
208	  }, [openTicket?.id, openTicket?.status]);
209	
210	  const shown = tickets.filter((t) => {
211	    if (!TICKET_FILTERS.find((f) => f.key === filter)!.match(t)) return false;
212	    const needle = q.trim().toLowerCase();
213	    if (!needle) return true;
214	    return t.subject.toLowerCase().includes(needle) || t.preview.toLowerCase().includes(needle);
215	  });
216	
217	  return (
218	    <div className="relative mx-auto flex w-full max-w-[1520px] flex-col gap-4">
219	      {/* ── Hero — the concept's own banner render as the background, bleeding
220	          past the header's own content and fading into the page instead of
221	          sitting inside a bordered card.
222	          `object-cover` was still cropping the right-side chips against a
223	          hard box edge (and scaling the art up to do it — the "too enlarged"
224	          complaint). Switched to `object-contain` inside its OWN sized,
225	          right-anchored box: the full image is always visible, never
226	          cropped, and a RADIAL mask (not just a bottom gradient) fades every
227	          edge of that box into the page — there is no edge left for a seam
228	          to show on, top/bottom/left/right alike. */}
229	      {/* A dark island: the scrim behind the heading is a hardcoded near-black
230	          rgba(4,8,20 regardless of theme, and a bare `text-white` heading over
231	          it had started resolving to near-black ink — dark text on a scrim of
232	          nearly the same darkness, which is as close to invisible as this
233	          gets without literally being it. Same fix as VpsHero/GameHero: the
234	          island re-themes everything inside at once (the buttons included)
235	          rather than patching each text-white by hand. */}
236	      <header className="nx-dark-island relative min-h-[420px] overflow-hidden">
237	        <div aria-hidden className="pointer-events-none absolute inset-y-0 right-0 w-[80%] max-w-[1150px]">
238	          <img src="/nx/art/support-hero-banner.webp" alt=""
239	               className="absolute inset-0 h-full w-full object-contain object-right"
240	               style={{
241	                 maskImage: "radial-gradient(62% 62% at 60% 50%, black 40%, transparent 85%)",
242	                 WebkitMaskImage: "radial-gradient(62% 62% at 60% 50%, black 40%, transparent 85%)",
243	               }} />
244	        </div>
245	        <span aria-hidden className="pointer-events-none absolute inset-0"
246	              style={{ background: "linear-gradient(90deg, rgba(4,8,20,0.92) 0%, rgba(4,8,20,0.74) 30%, rgba(4,8,20,0.28) 52%, transparent 72%)" }} />
247	        <div className="relative flex flex-col gap-5 px-6 py-7 sm:px-8 sm:py-9">
248	          <div className="flex max-w-[600px] flex-col gap-3.5">
249	            <span className="text-[12.5px] font-extrabold uppercase tracking-[0.24em] text-magenta">Support</span>
250	            <h1 className="text-[36px] font-extrabold leading-[1.08] tracking-[-0.03em] text-white sm:text-[46px]">
251	              We&apos;re here to{" "}
252	              <span className="bg-[linear-gradient(96deg,#a05cf0,#6f37d6)] bg-clip-text text-transparent">help.</span>
253	            </h1>
254	            <p className="max-w-[54ch] text-[14px] leading-[1.6] text-tx-mute">
255	              Get fast, reliable support from our team. Open a ticket, chat with us, or browse
256	              our help center — real people, real solutions, always on.
257	            </p>
258	          </div>
259	
260	          <div className="flex flex-wrap items-center gap-2.5">
261	            <button type="button"
262	                    onClick={() => { setTab("tickets"); backToList(); setNewTicketOpen(true); }}
263	                    className="btn-primary h-[40px] px-5 text-[13px]">
264	              + New Support Ticket
265	            </button>
266	            <button type="button" onClick={() => setTab("help")}
267	                    className="btn-secondary flex h-[40px] items-center gap-1.5 px-4 text-[13px]">
268	              <Icon name="lifebuoy" size={15} />
269	              Browse Help Center
270	            </button>
271	          </div>
272	
273	          <div className="flex flex-wrap items-center gap-x-7 gap-y-2.5">
274	            {[
275	              ["bolt", "Fast Response", "Usually within minutes"],
276	              ["users2", "Real People", "Expert support team"],
277	              ["shieldcheck", "Reliable Solutions", "Here when you need us"],
278	            ].map(([icon, t, d]) => (
279	              <span key={t} className="flex items-center gap-2.5">
280	                <Icon name={icon} size={20} />
281	                <span className="flex flex-col leading-tight">
282	                  <span className="text-[12px] font-bold text-white">{t}</span>
283	                  <span className="text-[10.5px] text-tx-faint">{d}</span>
284	                </span>
285	              </span>
286	            ))}
287	          </div>
288	        </div>
289	      </header>
290	
291	      {/* Only the concept's own real stat. "99.8% Customer Satisfaction" is
292	          not: there is no CSAT survey anywhere in this platform, so it stays
293	          out. Average response time IS real — see app/dashboard/support/page.tsx —
294	          computed from this customer's own tickets, not a marketing SLA. */}
295	      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
296	        {[
297	          { icon: "chat2", value: String(open), label: "Open tickets", tone: "blue" as const, bar: "#2f9bef" },
298	          { icon: "bellnotify", value: String(waitingOnYou), label: "Waiting for you", tone: "violet" as const, bar: "#8c3ae9" },
299	          { icon: "checkcircle", value: String(closedRecently), label: "Resolved (30 days)", tone: "mint" as const, bar: "#11c88e" },
300	          { icon: "clock2", value: avgResponseMin === null ? "—" : `${avgResponseMin}m`, label: "Avg response time", tone: "violet" as const, bar: "#d623e1" },
301	        ].map((s) => (
302	          <div key={s.label} className="relative">
303	            <StatCard bareIcon icon={s.icon} value={s.value} label={s.label} tone={s.tone}
