307	            <span aria-hidden className="pointer-events-none absolute inset-x-3.5 bottom-2.5 h-[3px] rounded-full opacity-70"
308	                  style={{ background: `linear-gradient(90deg, ${s.bar}, transparent)` }} />
309	          </div>
310	        ))}
311	      </div>
312	
313	      {/* Same underlined-text tab treatment as Billing (.nx-tab/.nx-tab-on,
314	          app/globals.css) instead of the pill/chip strip — one tab language
315	          across the account pages, not a per-page invention. */}
316	      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-rim-soft">
317	        <div className="flex flex-wrap items-center gap-6">
318	          {TABS.map((t) => (
319	            <button key={t.key} type="button" onClick={() => setTab(t.key)}
320	                    className={"nx-tab flex items-center gap-1.5 " + (tab === t.key ? "nx-tab-on" : "")}>
321	              {t.label}
322	              {t.key === "chat" && <span className="h-[6px] w-[6px] rounded-full bg-mint" aria-hidden />}
323	            </button>
324	          ))}
325	        </div>
326	        {tab === "tickets" && !openTicket && (
327	          <div className="mb-2 flex items-center gap-2">
