332	            </span>
333	            <select value={filter} onChange={(e) => setFilter(e.target.value)}
334	                    className="input h-[34px] w-[150px] py-0 text-[12px]">
335	              {TICKET_FILTERS.map((f) => (
336	                <option key={f.key} value={f.key}>{f.label}</option>
337	              ))}
338	            </select>
