592	type TicketThreadMessage = TicketThread["messages"][number];
593	
594	/** A run of consecutive messages from the same author, close enough together
595	 *  in time to read as one turn of the conversation. This is what turns a
596	 *  multi-image send (one text message + N attachment-only follow-ups, see
597	 *  `replyTicket` in lib/actions-support.ts) back into a single bubble with an
598	 *  image grid, instead of a wall of near-identical empty bubbles. */
599	type MessageCluster = { authorId: string; isStaff: boolean; authorName: string; lastAt: string; messages: TicketThreadMessage[] };
600	
601	const CLUSTER_GAP_MS = 60_000;
602	
603	function clusterMessages(messages: TicketThreadMessage[]): MessageCluster[] {
604	  const clusters: MessageCluster[] = [];
605	  for (const m of messages) {
606	    const last = clusters[clusters.length - 1];
607	    const gap = last ? new Date(m.createdAt).getTime() - new Date(last.lastAt).getTime() : Infinity;
608	    if (last && last.authorId === m.authorId && last.isStaff === m.isStaff && gap <= CLUSTER_GAP_MS) {
609	      last.messages.push(m);
610	      last.lastAt = m.createdAt;
611	    } else {
612	      clusters.push({ authorId: m.authorId, isStaff: m.isStaff, authorName: m.authorName, lastAt: m.createdAt, messages: [m] });
613	    }
614	  }
615	  return clusters;
616	}
