221	/* ══ LIGHT MODE ═══════════════════════════════════════════════════════════
222	   Everything in this app resolves through the tokens in @theme, so a light
223	   theme is a token swap rather than a per-component rewrite. `data-theme` is
224	   set on <html> by components/nx/ThemeToggle.tsx and pre-applied by an inline
225	   script in app/layout.tsx so the first paint is already correct.
226	
227	   THE SLATE RAMP IS INVERTED, and that is the load-bearing part. The dark
228	   theme remaps --color-slate-* so the app's ~4,700 existing `text-slate-*`
229	   usages resolve to Nexion's blue-tinted ramp, with 50 lightest and 950
230	   darkest. Body text is `text-slate-300`. Leaving that direction alone in
231	   light mode would paint pale text on a white page. So in light mode the ramp
232	   runs the other way: 50 is the darkest ink and 950 the lightest surface,
233	   which makes `text-slate-300` a readable dark grey and `bg-slate-900` a
234	   near-white panel, with no call site touched.
235	
236	   The ground stays DARKER than the cards here too — the same rule the dark
237	   theme states — so a white card still reads as lifted off the page. */
238	
239	html[data-theme="light"] {
240	  color-scheme: light;
241	
242	  --color-void: #dde5f2;
243	  --color-bg: #e9eff8;
244	  --color-surface: #ffffff;
245	  --color-well: #f3f7fc;
246	  --color-hover: #e8effa;
247	  --color-side: #00081a;          /* the rail stays dark — see .nx-dark-island */
248	  --color-rim: #d3dfef;
249	  --color-rim-soft: #e3eaf5;
250	  --color-rim-hi: #bfd0e7;
251	
252	  /* Accents pulled a little darker so they hold contrast on white. */
253	  --color-brand-500: #7a2fd0;
254	  --color-brand-400: #8c3ae9;
255	  --color-brand-300: #7a2fd0;
256	  --color-accent-blue: #1f63cc;
257	  --color-accent-cyan: #0b91ab;
258	  --color-cyan: #0b91ab;
259	  --color-blue: #1f63cc;
260	  --color-violet: #7a2fd0;
261	  --color-magenta: #b3159c;
262	  --color-mint: #0a9c6f;
263	  --color-amber: #b97708;
264	  --color-rose: #d02a54;
265	
266	  /* Inverted ramp — 50 is ink, 950 is paper. */
267	  --color-slate-50: #0a1829;
268	  --color-slate-100: #10243a;
269	  --color-slate-200: #18304a;
270	  --color-slate-300: #26405c;      /* body text */
271	  --color-slate-400: #4a6382;
272	  --color-slate-500: #607a99;
273	  --color-slate-600: #7b91ad;
274	  --color-slate-700: #a9bbd2;
275	  --color-slate-800: #d7e1ee;
276	  --color-slate-900: #e9eff8;
277	  --color-slate-950: #f5f8fc;
278	
279	  --color-tx: #081729;
280	  --color-tx-body: #223449;
281	  --color-tx-mute: #4a6182;
282	  --color-tx-dim: #47607f;
283	  --color-tx-faint: #64778e;
284	
285	  --fg: #0a1829;
286	  --fg-muted: #4a6182;
287	
288	  /* --color-white IS flipped to ink — second reversal, and this is the one
289	     that stays. Leaving it white made "text-white" (1,640 uses, almost all
290	     plain heading ink) disappear on every now-light card across the app —
291	     worse than the problem it was meant to solve, and the more visible bug.
292	     What actually broke last time was the OPACITY-MODIFIED variants —
293	     `bg-white/5`, `border-white/10`, `text-white/70` — which resolve through
294	     this same token and are calibrated as lighteners on a dark base. Those are
295	     decoupled below via attribute selectors on the literal class text, so they
296	     stop moving with this token at all. That is the fix; flipping the base
297	     value back and forth was chasing the wrong variable. */
298	  --color-white: #0a1829;
299	
300	  /* The navy ramp is the app's SURFACE ramp — bg-navy-900 (180 uses) and
301	     bg-navy-950 (140) are cards, panels and button faces. Left dark while the
302	     text flipped to ink, they were dark blocks with invisible labels on them.
303	     Inverted like slate: 950 was the darkest ground, so it becomes the
304	     lightest paper. */
305	  --color-navy-950: #ffffff;
306	  --color-navy-900: #fdfeff;
307	  --color-navy-850: #f6f9fd;
308	  --color-navy-800: #eff4fb;
309	  --color-navy-700: #e0e9f5;
310	  --color-navy-600: #d0dcee;
311	}
