412	}
413	/* A `text-white` heading is only ever meant as "the readable ink colour" in
414	   these components — never a colour chosen to sit on a saturated brand
415	   surface, which is what the VPS panel's own remaining `text-white` spots are
416	   (and why those were fixed by hand instead of matched here). Scoped to
417	   descendants of the two card patterns above, so nothing outside them moves. */
418	html[data-theme="light"] [class*="rgba(10,22,48"] [class~="text-white"],
419	html[data-theme="light"] [class*="rgba(6,14,36"] [class~="text-white"],
420	html[data-theme="light"] [class*="rgba(4,11,30"][class~="text-white"] {
