69	        {heroImage && (
70	          // eslint-disable-next-line @next/next/no-img-element -- a static hero illustration, not an optimizable content image.
71	          <img
72	            src={heroImage}
73	            alt=""
74	            aria-hidden
75	            className="pointer-events-none absolute -right-4 -top-6 hidden h-[280px] w-auto object-contain sm:block sm:h-[300px] lg:-right-2"
76	          />
