85	          </div>
86	          <div className="ml-auto flex flex-none items-center gap-4">
87	            <span className="hidden flex-col items-end gap-[3px] lg:flex">
88	              {tagline.map((l) => (
89	                <span key={l} className="text-[10px] font-semibold uppercase tracking-[0.28em] text-tx-faint">{l}</span>
90	              ))}
91	            </span>
