102	export function Panel({
103	  title, sub, action, className = "", bodyClass = "", style, glassId, children,
104	}: {
105	  title?: string; sub?: string; action?: React.ReactNode;
106	  className?: string; bodyClass?: string;
107	  /** For .card-glass's --tone custom property. */
108	  style?: React.CSSProperties;
109	  /** Mounts this panel's OWN <GlassFilters> and points --lens at it. Give
110	      every `card-glass` panel a DIFFERENT id — one filter definition shared
111	      by several cards is a confirmed way to ghost their text (see
