113	      lens distortion at all. */
114	  glassId?: string;
115	  children: React.ReactNode;
116	}) {
117	  const glassStyle = glassId
118	    ? { ...style, "--lens": `url(#${glassId})` } as React.CSSProperties
119	    : style;
120	  return (
121	    <section style={glassStyle} className={"card flex min-w-0 flex-col gap-3 p-4 " + className}>
122	      {glassId && <GlassFilters id={glassId} />}
123	      {(title || action) && (
124	        <div className="flex flex-none items-start justify-between gap-3">
125	          <span className="flex min-w-0 flex-col gap-0.5">
126	            {title && <span className="text-[15px] font-extrabold tracking-[-0.02em] text-white">{title}</span>}
127	            {sub && <span className="text-[11.5px] text-tx-faint">{sub}</span>}
128	          </span>
129	          {action}
130	        </div>
131	      )}
132	      <div className={"flex min-w-0 flex-col " + bodyClass}>{children}</div>
133	    </section>
134	  );
135	}
