   137	export function ReplyForm({ ticketId, onSent }: { ticketId: string; onSent?: () => void }) {
   138	  const [state, action, pending] = useActionState(replyTicket, {});
   139	  const [body, setBody] = useState("");
   140	  const composerRef = useRef<ReplyComposerHandle>(null);
   141	  // A reply has two outcomes and they want OPPOSITE things from the field, which
   142	  // is why simply making it controlled is not enough:
   143	  //   - rejected  → keep every character; React 19 would otherwise blank up to
   144	  //                 10,000 of them on the form-action submit, and the customer
   145	  //                 will not retype them.
   146	  //   - accepted  → clear it, or the sent reply sits there looking unsent and
   147	  //                 gets sent twice.
   148	  // So the field is controlled and cleared only on a submit that came back
   149	  // without an error, watching the pending edge rather than the state shape
   150	  // (the action returns `{}` for success, which is indistinguishable from its
   151	  // initial value).
   152	  const wasPending = useRef(false);
   153	  useEffect(() => {
   154	    if (wasPending.current && !pending && !state?.error) {
   155	      setBody("");
   156	      composerRef.current?.resetAttachment();
   157	      // Optional — the Support page's inline thread view (no page navigation,
   158	      // so no revalidatePath re-render) uses this to refetch the thread right
   159	      // away instead of waiting for its own poll tick.
   160	      onSent?.();
   161	    }
   162	    wasPending.current = pending;
   163	  }, [pending, state, onSent]);
   164	  return (
   165	    <form action={action} className="space-y-3">
   166	      <input type="hidden" name="ticketId" value={ticketId} />
   167	      {state?.error && <p className="text-sm text-red-400">{state.error}</p>}
   168	      <ReplyComposer
   169	        ref={composerRef}
   170	        value={body}
   171	        onChange={setBody}
   172	        placeholder="Write a reply…"
   173	        disabled={pending}
   174	        onTyping={() => void pingTyping(ticketId)}
   175	      />
   176	      <div className="flex justify-end">
   177	        <button className="btn-primary px-6" disabled={pending}>
   178	          {pending ? "Sending…" : "Send reply"}
   179	        </button>
   180	      </div>
   181	    </form>
   182	  );
   183	}
