 51	import { useEffect, useState, useTransition } from "react";
 52	import { editTicketMessage } from "@/lib/actions-support";
 53	import { TicketBody } from "./TicketBody";
 54	
 55	const EDIT_WINDOW_MS = 5 * 60_000;
 56	
 57	/**
 58	 * Renders a single message's body, with an "Edit" affordance that appears
 59	 * only for the message's own author and only within 5 minutes of sending —
 60	 * matched to the server-side window `editTicketMessage` (lib/actions-support.ts)
 61	 * actually enforces. This client-side countdown is a UX nicety ONLY: hiding
 62	 * the button here is not what stops a late edit, the server re-checks
 63	 * `createdAt` itself and rejects regardless of what this component shows.
 64	 *
 65	 * The "(edited)" label is shown to BOTH admin and customer views (pass this
 66	 * component to either) — unlike read receipts, an edit marker is a
 67	 * transparency signal both parties see.
 68	 */
 69	export function EditableMessageBody({
 70	  messageId,
 71	  initialBody,
 72	  createdAtIso,
 73	  editedAtIso,
 74	  canEditPermission,
 75	  bodyClassName,
 76	}: {
 77	  messageId: string;
 78	  initialBody: string;
 79	  createdAtIso: string;
 80	  editedAtIso: string | null;
 81	  /** Author-matches-viewer AND ticket-not-closed — everything except the time window. */
 82	  canEditPermission: boolean;
 83	  bodyClassName: string;
 84	}) {
 85	  const [body, setBody] = useState(initialBody);
 86	  const [editedAt, setEditedAt] = useState(editedAtIso);
 87	  const [editing, setEditing] = useState(false);
 88	  const [draft, setDraft] = useState(initialBody);
 89	  const [error, setError] = useState<string | null>(null);
 90	  const [withinWindow, setWithinWindow] = useState(
 91	    () => Date.now() - new Date(createdAtIso).getTime() < EDIT_WINDOW_MS
 92	  );
 93	  const [pending, start] = useTransition();
 94	
 95	  useEffect(() => {
 96	    if (!canEditPermission || !withinWindow) return;
 97	    const id = window.setInterval(() => {
 98	      const stillWithin = Date.now() - new Date(createdAtIso).getTime() < EDIT_WINDOW_MS;
 99	      setWithinWindow(stillWithin);
100	      if (!stillWithin) window.clearInterval(id);
101	    }, 5_000);
102	    return () => window.clearInterval(id);
103	  }, [canEditPermission, withinWindow, createdAtIso]);
104	
105	  function save() {
106	    setError(null);
107	    start(async () => {
108	      const res = await editTicketMessage(messageId, draft);
109	      if (res?.error) {
110	        setError(res.error);
111	        return;
112	      }
113	      setBody(draft.trim());
114	      setEditedAt(new Date().toISOString());
115	      setEditing(false);
116	    });
117	  }
118	
119	  if (editing) {
120	    return (
121	      <div className="space-y-2">
122	        <textarea
123	          className="input min-h-20 w-full resize-y text-sm"
124	          value={draft}
125	          onChange={(e) => setDraft(e.target.value)}
126	          disabled={pending}
127	          autoFocus
128	        />
129	        {error && <p className="text-xs text-red-400">{error}</p>}
130	        <div className="flex items-center gap-2">
131	          <button
132	            type="button"
133	            className="btn-primary px-3 py-1 text-xs"
134	            disabled={pending || draft.trim().length < 2}
135	            onClick={save}
136	          >
137	            {pending ? "Saving…" : "Save"}
138	          </button>
139	          <button
140	            type="button"
141	            className="btn-ghost px-3 py-1 text-xs"
142	            disabled={pending}
143	            onClick={() => {
144	              setDraft(body);
145	              setError(null);
146	              setEditing(false);
147	            }}
148	          >
149	            Cancel
150	          </button>
151	        </div>
152	      </div>
153	    );
154	  }
155	
156	  return (
157	    <div>
158	      <TicketBody text={body} className={bodyClassName} />
159	      <div className="mt-1 flex items-center gap-2">
160	        {editedAt && <span className="text-[10px] text-slate-500">(edited)</span>}
161	        {canEditPermission && withinWindow && (
162	          <button
163	            type="button"
164	            className="text-[10px] text-slate-500 underline decoration-dotted hover:text-brand-300"
165	            onClick={() => {
166	              setDraft(body);
167	              setEditing(true);
168	            }}
169	          >
170	            Edit
171	          </button>
172	        )}
173	      </div>
174	    </div>
175	  );
176	}

