367	export function Shell({ children, user, badges = {}, notifications = [] }: {
368	  children: React.ReactNode; user: User; badges?: Badges; notifications?: Note[];
369	}) {
370	  // The composer lives at the SHELL level, exactly as it does in the portal
371	  // shell this one replaces. Two reasons it cannot move down into the mail
372	  // page: App Router keeps the shell mounted across in-portal navigation, so an
373	  // open (or minimized) composer and its in-progress draft survive moving
374	  // between pages; and MailClient calls `useCompose()` unconditionally, which
375	  // THROWS when no provider sits above it.
376	  //
377	  // That throw is not hypothetical — it took the whole inbox down. This shell
378	  // reproduced the portal shell's layout but not this provider, and the crash
379	  // is invisible until an account has a real, reachable mailbox: with none, the
380	  // mail page short-circuits to "No email plan yet" and never renders
381	  // MailClient at all. The first account with working mail gets an error
382	  // boundary instead of an inbox.
383	  // The SECOND provider this shell failed to reproduce, and the same bug
384	  // shape: `OpenTerminalButton` calls `useTerminalDock()`, which throws outside
385	  // a provider, so every RUNNING VPS detail page — and any game server whose
386	  // family check sent it down the VPS branch — rendered an error boundary
387	  // instead of a server. Invisible from the routes a smoke test walks, because
388	  // the button only mounts on a server's own page when it is running.
389	  //
390	  // MatrixPanel is the same omission a third time. It is mounted HERE rather
391	  // than by /dashboard/build's page because the App Router unmounts a page's
392	  // subtree on every route change, and Matrix's whole promise is that you can
393	  // leave a build running, go look at something else in the portal, and come
394	  // back to it still running. Mounted at the shell, its consoles and their
395	  // websockets outlive navigation. It renders nothing until the route is first
396	  // visited, so accounts that never open it pay nothing for it.
397	  return (
398	    <ComposeProvider>
399	      <TerminalDockProvider>
400	        <ShellInner user={user} badges={badges} notifications={notifications} matrixPanel={<MatrixPanel />}>
401	          {children}
402	        </ShellInner>
403	      </TerminalDockProvider>
404	    </ComposeProvider>
405	  );
406	}
