1	import type { Metadata } from "next";
2	import { Geist, Geist_Mono } from "next/font/google";
3	import "./globals.css";
4	
5	// Brand typeface (Nexion), loaded once site-wide and self-hosted by next/font (no CDN at
6	// runtime). Exposed as CSS variables that globals.css maps onto Tailwind's
7	// --font-sans / --font-mono, so every page + the dashboard share one typeface
8	// instead of the browser default. Geist Sans + Geist Mono — one matched family
9	// for both UI text and data/code, replacing the previous Plus Jakarta Sans /
10	// JetBrains Mono pairing (see components/customer/PaymentStep.tsx, which used
11	// to load its own separate copy of Geist just to match Stripe's card fields —
12	// now redundant, since the whole page is Geist).
13	const nxSans = Geist({ subsets: ["latin"], variable: "--font-nx-sans", display: "swap" });
14	const nxMono = Geist_Mono({ subsets: ["latin"], variable: "--font-nx-mono", display: "swap" });
15	import { Analytics } from "@/components/marketing/Analytics";
16	import { TrackingProvider } from "@/components/marketing/TrackingProvider";
17	import MetaPixelTracker from "@/components/marketing/MetaPixelTracker";
18	import { OrganizationJsonLd } from "@/components/marketing/StructuredData";
19	import CookieConsent from "@/components/marketing/CookieConsent";
20	import LiveChat from "@/components/marketing/LiveChat";
21	import ChatWidget from "@/components/ChatWidget";
22	import { SandboxBanner } from "@/components/SandboxBanner";
23	import { SANDBOX } from "@/lib/sandbox";
24	
25	const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";
26	const DESCRIPTION =
27	  "High-performance NVMe VPS hosting with instant deployment — control panels, game servers, VPNs, and domains. Deploy a server in seconds with full root access and a dedicated IP option.";
28	
29	/**
30	 * Root metadata. A function, not a constant, because the platform name comes from
31	 * Settings → General (`brand_name`) — every string below used to hardcode "Nxeon", so
32	 * renaming the platform in the admin panel changed the browser tab, the per-page title
33	 * template, the Open Graph site name and the author/creator/publisher meta tags on exactly
34	 * nothing. Next.js only awaits a DB read here if the export is `generateMetadata`.
35	 *
36	 * Still hardcoded and out of scope for this pass: the schema.org JSON-LD in
37	 * components/marketing/StructuredData.tsx (Organization, Product, BlogPosting).
38	 *
39	 * Failure of the settings read is non-fatal on purpose and mirrors the `livechat_snippet`
40	 * read below: if Postgres is unreachable, the correct outcome is a page that renders with
41	 * the default title, not a 500 on the root layout that takes the whole site (including
42	 * /status) down with it.
43	 */
44	export async function generateMetadata(): Promise<Metadata> {
45	  // Only used when @/lib/settings cannot even be loaded. Kept a local literal rather
46	  // than a static SETTINGS_DEFAULTS import so the root layout still has no top-level
47	  // dependency on Prisma — the same reason the livechat read below is a dynamic import.
48	  let brand = "Nxeon";
49	  let fbDomainVerify = "";
50	  try {
51	    const { getSetting, SETTINGS_DEFAULTS } = await import("@/lib/settings");
52	    brand = (await getSetting("brand_name")).trim() || SETTINGS_DEFAULTS.brand_name;
53	    fbDomainVerify = (await getSetting("meta_domain_verification")).trim();
54	  } catch {
55	    /* settings unavailable — fall back to the built-in brand name */
56	  }
57	  return {
58	    metadataBase: new URL(APP_URL),
59	    // Meta Business domain verification — emits <meta name="facebook-domain-verification">
60	    // only when an operator has set the token in admin → Marketing → Tracking.
61	    ...(fbDomainVerify
62	      ? { verification: { other: { "facebook-domain-verification": fbDomainVerify } } }
63	      : {}),
64	    title: {
65	      default: `${brand} — Cloud VPS Hosting, Game Servers & Domains`,
66	      template: `%s — ${brand}`,
67	    },
68	    description: DESCRIPTION,
69	    applicationName: brand,
70	    keywords: [
71	      "VPS hosting",
72	      "cloud VPS",
73	      "game server hosting",
74	      "Minecraft server hosting",
75	      "NVMe VPS",
76	      "affordable VPS",
77	      "domain registration",
78	      "dedicated IP",
79	      "Singapore VPS",
80	      "cPanel hosting",
81	    ],
82	    authors: [{ name: brand }],
83	    creator: brand,
84	    publisher: brand,
85	    alternates: { canonical: "/" },
86	    openGraph: {
87	      type: "website",
88	      siteName: brand,
89	      url: APP_URL,
90	      locale: "en_US",
91	    },
92	    twitter: {
93	      card: "summary_large_image",
94	    },
95	    robots: {
96	      index: true,
97	      follow: true,
98	      googleBot: {
99	        index: true,
100	        follow: true,
101	        "max-image-preview": "large",
102	        "max-snippet": -1,
103	        "max-video-preview": -1,
104	      },
105	    },
106	    icons: {
107	      icon: [
108	        { url: "/favicon.ico", sizes: "any" },
109	        { url: "/icon-192.png", sizes: "192x192", type: "image/png" },
110	        { url: "/icon-512.png", sizes: "512x512", type: "image/png" },
111	      ],
112	      shortcut: "/favicon.ico",
113	      apple: "/apple-touch-icon.png",
114	    },
115	    manifest: "/manifest.webmanifest",
116	  };
117	}
118	
119	export default async function RootLayout({ children }: { children: React.ReactNode }) {
120	  // Admin-configured live-chat snippet (trusted input — only staff can set it).
121	  let chatSnippet = "";
122	  try {
123	    const { getSetting } = await import("@/lib/settings");
124	    chatSnippet = (await getSetting("livechat_snippet", "")) ?? "";
125	  } catch {
126	    /* settings unavailable — chat stays off */
127	  }
128	
129	  // Signed-in viewer (if any) so the chat widget prefills name/email and doesn't
130	  // re-ask; anonymous visitors are required to provide them. Best-effort.
131	  let chatViewer: { name: string | null; email: string | null } | null = null;
132	  try {
133	    const { currentUser } = await import("@/lib/auth");
134	    const u = await currentUser();
135	    if (u) chatViewer = { name: u.name ?? null, email: u.email ?? null };
136	  } catch {
137	    /* not signed in / auth unavailable — widget will ask for details */
138	  }
139	  return (
140	    // `nx-has-banner` publishes the sandbox banner's height as --nx-chrome.
141	    // Full-height "app frame" routes (the mail client) size themselves to the
142	    // viewport minus the fixed chrome above them, and this banner is real
143	    // chrome here that does not exist in production — without it the mail page
144	    // would be exactly one banner too tall and scroll in the sandbox only.
145	    <html lang="en" className={`${nxSans.variable} ${nxMono.variable}`} suppressHydrationWarning>
146	      <head>
147	        {/* Applies the saved theme BEFORE first paint. A React effect runs after
148	            hydration, which is one paint too late — every load would flash the
149	            dark theme at anyone who chose light. Deliberately tiny, deliberately
150	            blocking, and it fails closed to dark.
151	
152	            Gated to /dashboard: `nx-theme` lives in localStorage, which is
153	            shared by the WHOLE origin, not just the portal — the toggle only
154	            renders inside the dashboard shell, but without this check, a
155	            customer who ever switched to light mode there got the marketing
156	            site (and login, and a client-side nav back from the dashboard)
157	            rendered light too, since this script has no other way to know
158	            which surface it is painting. Marketing/login never had a light
159	            theme built for them; they must always fail closed to dark. */}
160	        <script
161	          dangerouslySetInnerHTML={{
162	            __html:
163	              "try{if(location.pathname.startsWith('/dashboard')&&localStorage.getItem('nx-theme')==='light')" +
164	              "document.documentElement.setAttribute('data-theme','light')}catch(e){}",
165	          }}
166	        />
167	      </head>
168	      <body className={SANDBOX ? "nx-has-banner" : undefined}>
169	        <SandboxBanner />
170	        {children}
171	        <CookieConsent />
172	        <LiveChat snippet={chatSnippet} />
173	        <ChatWidget viewer={chatViewer} />
174	        <OrganizationJsonLd />
175	        <Analytics />
176	        <TrackingProvider />
177	        <MetaPixelTracker />
178	      </body>
179	    </html>
180	  );
181	}
